#include "simulation.hpp"
#include "controls.hpp"
#include <iostream>
#include <stdexcept>
using namespace ofo;
void check(bool x,const char*s){if(!x)throw std::runtime_error(s);}
Geometry plane(){Geometry g;g.materials.push_back({});Mesh m;m.vertices={{{-500,0,-500}},{{500,0,-500}},{{500,0,500}},{{-500,0,500}}};m.indices={0,2,1,0,3,2};g.meshes.push_back(m);return g;}
int main(int argc,char**argv){try{Resources r(argv[1]);auto c=load_vehicle(r,3,argc>2?argv[2]:"");auto g=plane();Mat spawn=translate({0,1,0});Simulation a(g,c,spawn),b(g,c,spawn);for(int i=0;i<300;i++){a.step({});b.step({});}check(std::isfinite(a.state().car[13])&&a.state().car[13]>-.2,"settled finite body");for(int i=0;i<500;i++){Input in;in.throttle=1;a.step(in);b.step(in);}auto s=a.state();check(std::abs(s.speed)>3,"driven acceleration");CarDisplayInfo display{c.name,"999999 kg"};check(a.state().car==b.state().car,"fixed step determinism independent of display data");float before=std::abs(s.speed);for(int i=0;i<200;i++){Input in;in.brake=1;a.step(in);}check(std::abs(a.state().speed)<before*.8,"braking slows");Input pedals;State rev;rev.speed=-10;rev.gear=-1;pedals.throttle=1;direction_pedals(pedals,rev);check(pedals.brake==1&&pedals.throttle==0,"forward pedal brakes reverse motion");State fwd;fwd.speed=10;pedals={};pedals.brake=1;direction_pedals(pedals,fwd);check(pedals.brake==1&&pedals.throttle==0,"brake remains brake while forward");fwd.speed=0;direction_pedals(pedals,fwd);check(pedals.throttle==-1&&pedals.brake==0,"reverse selected after stop");Simulation reverse(g,c,spawn);for(int i=0;i<300;i++)reverse.step({});for(int i=0;i<300;i++){Input in;in.throttle=-1;reverse.step(in);}check(reverse.state().speed < -2,"reverse acceleration");float reverse_before=std::abs(reverse.state().speed);for(int i=0;i<150;i++){Input in;in.throttle=1;direction_pedals(in,reverse.state());reverse.step(in);}check(std::abs(reverse.state().speed)<reverse_before,"reverse can brake normally");Simulation manual(g,c,spawn);for(int i=0;i<300;i++)manual.step({});Input shift;shift.automatic=false;shift.shift=1;manual.step(shift);check(manual.state().gear==2,"manual upshift");shift.shift=0;shift.throttle=1;shift.nitro=true;for(int i=0;i<200;i++)manual.step(shift);check(manual.state().gear==2,"manual holds gear");auto preserved=manual.state();manual.recover();check(manual.state().time==preserved.time&&manual.state().nitro==preserved.nitro,"recovery preserves timer/nitro");shift.shift=-1;manual.step(shift);check(manual.state().gear==0,"downshift from recovered first gear selects documented neutral");std::cout<<"speed="<<before<<" brake="<<a.state().speed<<" ride="<<s.car[13]<<" core simulation passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
